#pragma once

// The disc's program version and the harness's program addresses in it.
//
// The harness's tests name the original's functions, call sites and globals by their NTSC-U addresses (US 1.00 and 1.10
// ship the same CORE.GT3). On a PAL or NTSC-J disc the same code sits elsewhere: pa() translates an NTSC-U address through
// the version table program_map.inc (one row per address the harness uses, a column per sim::Program: NTSC-U, PAL, NTSC-J,
// then the later builds, Gran Turismo Concept's; generated by tools/re/program_map.py: GT3's releases by version_map.py,
// which matches the functions of two programs by their code with the relocations masked and maps an address inside a
// function through the aligned instructions; the later builds, another compiler's code, by build_map.py's chain). Tests
// that run on every version are registered with DIFF_TEST_ALL (harness.h); the others are skipped on a program other than
// NTSC-U.

#include "base/bytes.h"
#include "sim/exact/program_data.h"

#include <optional>
#include <string>

namespace gt3r::diff {

using sim::exact::Program;

// The disc's program (main sets it from ProgramData's version check; none: not a known program).
void set_program(std::optional<Program> p);
std::optional<Program> disc_program();
// Where ProgramData's locator found the disc's program tables (main gives them; 0: not found). On a later build pa() of
// an address inside one of the tables is the located table's (the version table's data rows of another compiler's
// program come from votes and are not all right).
void set_table_addresses(const sim::exact::ProgramData& d);
// The behaviour the exact tests check on the disc: its release's own rules at its own rate (release_behaviour). On a later
// build with the routines its program has of a GT3 release's rules (ProgramData's: a routine recognised as PAL's variant
// follows PAL's rule there); main gives the disc's ProgramData. GT3R_RULES_AS=<rule index>:<program index>,... sets a
// routine's variant by hand on a later build (experiments: does this build's routine follow that release's rule?).
sim::Behaviour disc_behaviour();
void set_disc_behaviour(sim::exact::ProgramData d);
// The disc's program, or NTSC-U when it is not known (the tests then fail where they need a translation).
Program program();
bool ntsc_u();

// The address in the disc's program of NTSC-U program address `a`: `a` itself on NTSC-U; throws std::runtime_error when
// the version table has no row for it, or the row says the address has no counterpart in this program.
u32 pa(u32 a);
// While one of these lives, on a later build (Gran Turismo Concept) pa() gives 0 for an address without a counterpart
// instead of throwing, and lists it (a probe at 0 is not installed, a return address never equals 0): for the tests whose
// checks hang on places inside routines another compiler arranged otherwise. GT3's releases still throw.
struct LenientPlaces {
    LenientPlaces();
    ~LenientPlaces();
    // The NTSC-U addresses asked for and not found since this one was made, "1F3CC8 1F3D00 ...".
    std::string missing() const;
};
// A routine only the later builds have (a sim::Rule after GroundMiss) as an address key for pa() / Pa: the routine itself
// (ProgramData's rule site) and its call in the race step 0x1F39D8 (the jal found in the disc's step). pa() gives 0 for
// one the disc's program does not have, has_pa() false; GT3's releases have none (but the places marked `every`).
constexpr u32 kLaterKey = 0xF0000000u;
constexpr u32 later_fn(sim::Rule r) { return kLaterKey | u32(r) << 8; }
constexpr u32 later_site(sim::Rule r) { return kLaterKey | u32(r) << 8 | 1; }
// Where the routine's second call returns (special car 1's mood: its rival level's).
constexpr u32 later_tap(sim::Rule r) { return kLaterKey | u32(r) << 8 | 2; }
// A place inside a later build's routine that GT3's code has no counterpart for (another compiler: a call made twice, a
// call made by a jump), found in the disc's program by the routine's calls: the `nth` call (jal or j, from 1) to `target`
// inside `fn` (NTSC-U addresses, or later_fn() keys; target 0: any call; within `span` bytes of the routine's start), plus
// `add` bytes.
struct LaterPlace {
    u32 fn, target;
    int nth;
    s32 add;
    u32 span = 0x400;
    bool every = false; // found in GT3's programs too (a place another compiler moved, in a routine every program has)
};
enum LaterPlaceId : u32 {
    kPitExitLine6Return, // the pit exit 0x1E3BF0's second line request (line 6: a later build's has a call for each line)
    kPodStopDriverCall,  // the pod race's line rule's call of the stop driver (later 0x1EE7F0 -> 0x1EF8A0; the call itself)
    kDecideStopLapReturn, // the AI decision's lap length for its stop point (0x1F7AE0 -> 0x1F2EA8, which jumps to 0x18FA10)
    kPassByReturn,        // the race step's call of the pass-by states 0x1F59B0 returns here (every program)
    kLaterPlaces
};
constexpr u32 later_place(LaterPlaceId id) { return kLaterKey | 0x00FF0000u | u32(id); }
constexpr bool later_key(u32 a) { return a >= kLaterKey; }
// main gives the places: the rules' routines from ProgramData, the calls from the program image (loaded at `load`).
void set_later_places(const sim::exact::ProgramData& d, ByteSpan program, u32 load);
// pa() for any program `p`.
u32 pa(u32 a, Program p);
// Whether pa(a) has an answer.
bool has_pa(u32 a);
// The NTSC-U address of program address `x` of the disc's program (a row's reverse; x itself when there is none).
u32 ntsc_u_address(u32 x);

// A race conductor's (DynamicsConductor and its race modes') virtual slot in the disc's program by its NTSC-U slot: the
// NTSC-J classes have no virtual 4 (the rubber band's time scale 0x1ECEB8), so their later slots are one lower; throws
// std::runtime_error for slot 4 on NTSC-J.
// The later builds (Gran Turismo Concept): 2001 Tokyo's and 2002 Tokyo-Seoul v1.02's classes keep NTSC-U's slots; from
// v2.00 on two more virtuals at 15 and 16, so NTSC-U's slots from 15 on are two higher.
int conductor_slot(int ntsc_u_slot);

// ---- record layouts of the later builds (Gran Turismo Concept; every one of them the same) -----------------------------------
// The car record: unchanged up to +0x1327, one word more at +0x1328 (record size 0x16E0); an NTSC-U offset in the disc's
// record, and the record's size. car_exact::snapshot() / write_car() give and take records in NTSC-U's layout.
u32 car_off(u32 ntsc_u_offset);
u32 car_stride();
// The same for an offset from the record's dynamics block F (car + 0xF84).
inline u32 f_off(u32 ntsc_u_f_offset) { return car_off(0xF84 + ntsc_u_f_offset) - 0xF84; }
// The inserted word's place in the disc's record (0: the record has none).
u32 car_extra_word();
// A conductor offset (NTSC-U's: cars at +0xC8, the configuration at +0xB7A8, the collision manager at +0xBBB4, the race
// rule block at +0xE340, the vtable at +0xE3A8): the later builds' eight car slots are 4 bytes longer each and 0x40 bytes
// follow them (everything from +0xB7A8 is 0x60 higher), and their vtable pointer is at +0xE47C. Offsets inside a car slot
// map through car_off().
u32 cond_off(u32 ntsc_u_offset);
// A race entry's offset (RaceEntryCar: the equipment at +0x20, the time records at +0x210 .. +0x11FC, the input object at
// +0x20DC, the grid slot, the settings and the condition words after it): the later builds' entries are 0x44 bytes longer
// before +0x20DC. entry_size(): what the harness allocates for one.
u32 entry_off(u32 ntsc_u_offset);
u32 entry_size();
// The event's database holder (race info + 0x28: +0 the database, +0x18 the event's record, +0x20 the course id): from
// 2002 Tokyo-Seoul v2.00 on a word sits before the record, so the record and what follows are 8 higher.
u32 holder_off(u32 ntsc_u_offset);
// The same for an offset from conductor + 0x8000.
inline u32 k_off(u32 ntsc_u_k_offset) { return cond_off(0x8000 + ntsc_u_k_offset) - 0x8000; }
// A conductor offset that reads as the disc's wherever it is used as a u32 (for constexpr names).
struct Co {
    u32 ntsc_u = 0;
    constexpr Co() = default;
    constexpr Co(u32 o) : ntsc_u(o) {}
    operator u32() const { return cond_off(ntsc_u); }
};
// A register of the race step 0x1F39D8 (the probes read it) by its NTSC-U number: NTSC-J's step keeps the conductor in $s2
// (NTSC-U $s4), the car index in $s1 ($s3) and the step-runs flag in $s3 ($s1).
int race_step_reg(int ntsc_u_reg);
// A race event queue id (race info + 0x84) of the disc's program as NTSC-U numbers it (the exact core's RaceEvent ids):
// NTSC-J's program has no general time event (NTSC-U's 14, RaceDisplayGeneralTimeEvent) and numbers the events from NTSC-U's
// 15 on one lower (its 14 the time difference, 15 the lap difference, 16 the speed, 17 the information, 18 the new record).
// The later builds have one more id, 11 (a car that missed its stops, docs/specs/physics.md §14.5; given as
// sim::exact::kStopsMissedEvent), and number GT3's ids from 11 on one higher.
s32 ntsc_u_event(s32 id);
// The queue's count of entries (race info + 0x84 + this): after the counts per id, which the later builds have four more of.
u32 queue_count_off();
// A race info offset by its NTSC-U value: what follows the queue's count (the session's times, +0x8A4 on) is 4 higher there.
inline u32 info_off(u32 ntsc_u_offset) { return ntsc_u_offset >= 0x89C ? ntsc_u_offset + queue_count_off() - 0x818 : ntsc_u_offset; }

// An NTSC-U program address that reads as the disc's (pa()) wherever it is used as a u32, for the harness's constexpr
// tables of functions, call sites and globals (they are built before the disc's program is known). 0 stays 0 (none).
struct Pa {
    u32 ntsc_u = 0;
    constexpr Pa() = default;
    constexpr Pa(u32 a) : ntsc_u(a) {}
    operator u32() const { return ntsc_u ? pa(ntsc_u) : 0; }
};

// The exact core's program tables by their NTSC-U addresses (ProgramData knows them only by id): the table and offset of
// an NTSC-U table byte (std::out_of_range for any other address), the NTSC-U start of a table.
struct TableByte {
    sim::exact::ProgramData::Table table;
    u32 off;
};
TableByte table_byte(u32 ntsc_u_addr);
u32 ntsc_u_table(sim::exact::ProgramData::Table t);
// A table byte changed in a program data copy, by its NTSC-U address.
void poke_table(sim::exact::ProgramData& d, u32 ntsc_u_addr, u8 v);

} // namespace gt3r::diff
